def archive_existing_competition(apps, schema_editor):
    alias = schema_editor.connection.alias
    config = apps.get_model("songs", "ContestSettings").objects.using(alias).first()
    models_to_scope = [
        apps.get_model("songs", name) for name in ("Chart", "Song", "CompetitionPhase")
    ]
    if config is None and not any(
        model.objects.using(alias).exists() for model in models_to_scope
    ):
        return
    settings = (
        {
            field: getattr(config, field)
            for field in (
                "submissions_open",
                "reviews_open",
                "reviews_per_chart",
                "max_score",
                "max_favorites",
            )
        }
        if config
        else {}
    )
    competition = (
        apps.get_model("songs", "Competition")
        .objects.using(alias)
        .create(
            name="历史比赛", status="archived", archived_at=timezone.now(), **settings
        )
    )
    for model in models_to_scope:
        model.objects.using(alias).update(competition_id=competition.pk)


